WITH cleaned AS (SELECT id, customer_id, start_date, end_date, status, CEIL(monthly_fee) monthly_fee_whole FROM subscriptions WHERE start_date >= TO_DATE('2023-03-13')), latest AS (SELECT *, RANK() OVER (PARTITION BY status ORDER BY start_date DESC) AS rank_in_group FROM cleaned QUALIFY rank_in_group = 1), latest_subscriptions AS (SELECT id, monthly_fee_whole, rank_in_group FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY end_date, id) AS rank_in_group_2 FROM latest) ranked WHERE rank_in_group_2 = 1), kept_keys AS (SELECT id FROM latest_subscriptions EXCEPT SELECT id FROM subscriptions WHERE end_date <= '2024-11-30'), verified AS (SELECT s.* FROM latest_subscriptions s INNER JOIN kept_keys k ON s.id = k.id), enriched AS (SELECT *, DENSE_RANK() OVER w_hist monthly_fee_whole_dense_rank, RANK() OVER (ORDER BY monthly_fee_whole DESC NULLS LAST) monthly_fee_whole_rank, CUME_DIST() OVER (ORDER BY monthly_fee_whole DESC) monthly_fee_whole_cume_dist FROM verified WINDOW w_hist AS (ORDER BY monthly_fee_whole NULLS LAST)), metrics AS (SELECT *, CUME_DIST() OVER w_ordered monthly_fee_whole_cume_dist_cume_dist FROM enriched WINDOW w_ordered AS (ORDER BY monthly_fee_whole_cume_dist DESC NULLS FIRST)), metrics_subscriptions AS (SELECT id, monthly_fee_whole, monthly_fee_whole_dense_rank, DENSE_RANK() OVER w_recent monthly_fee_whole_rank_dense_rank, DENSE_RANK() OVER (ORDER BY monthly_fee_whole_dense_rank DESC NULLS LAST) monthly_fee_whole_dense_rank_dense_rank FROM metrics WHERE monthly_fee_whole_dense_rank = 5 WINDOW w_recent AS (ORDER BY monthly_fee_whole_rank DESC NULLS FIRST)) SELECT CASE WHEN monthly_fee_whole_dense_rank >= 7 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_whole_dense_rank_tier, CASE WHEN monthly_fee_whole_rank_dense_rank >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS monthly_fee_whole_rank_dense_rank_tier, CASE WHEN monthly_fee_whole_dense_rank_dense_rank >= 7 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_whole_dense_rank_dense_rank_tier, APPROX_PERCENTILE(monthly_fee_whole, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_whole_quartiles, COUNT(*) AS row_count, ROUND(AVG(monthly_fee_whole_rank_dense_rank), 2) AS avg_monthly_fee_whole_rank_dense_rank, APPROX_PERCENTILE(monthly_fee_whole_dense_rank_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_whole_dense_rank_dense_rank_quartiles FROM metrics_subscriptions GROUP BY GROUPING SETS ((CASE WHEN monthly_fee_whole_dense_rank >= 7 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN monthly_fee_whole_rank_dense_rank >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN monthly_fee_whole_dense_rank_dense_rank >= 7 THEN 'LARGE' ELSE 'SMALL' END), (CASE WHEN monthly_fee_whole_dense_rank >= 7 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN monthly_fee_whole_rank_dense_rank >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END), (CASE WHEN monthly_fee_whole_dense_rank >= 7 THEN 'LARGE' ELSE 'SMALL' END)) ORDER BY monthly_fee_whole_rank_dense_rank_tier DESC
